const CODE_KEY='battle-of-rah-access-code-v1';
let accessMode='unlock',accessFailures=0,accessLockedUntil=0;
const makeSalt=()=>{let bytes=new Uint8Array(16);if(globalThis.crypto?.getRandomValues)crypto.getRandomValues(bytes);else for(let i=0;i<bytes.length;i++)bytes[i]=Math.floor(Math.random()*256);return [...bytes].map(x=>x.toString(16).padStart(2,'0')).join('')};
async function codeDigest(code,salt){
 const input=new TextEncoder().encode('Battle-of-Rah-v1:'+salt+':'+code);
 if(globalThis.crypto?.subtle){let result=await crypto.subtle.digest('SHA-256',input);return [...new Uint8Array(result)].map(x=>x.toString(16).padStart(2,'0')).join('')}
 let a=2166136261;for(const byte of input){a=Math.imul(a^byte,16777619)}return 'fallback-'+(a>>>0).toString(16);
}
function accessError(message){document.getElementById('accessError').textContent=message}
function openAccess(mode){
 accessMode=mode;const setup=mode==='setup',change=mode==='change',m=document.getElementById('scorekeeperAccess');
 document.getElementById('accessTitle').textContent='SCOREKEEPER ACCESS';
 document.getElementById('accessDescription').textContent='Enter your organizer access code to unlock scoreboard editing, player photos and live play updates.';
 document.getElementById('accessSubmit').textContent='UNLOCK SCOREKEEPER';
 const confirm=document.getElementById('accessConfirm'),label=document.getElementById('confirmLabel');confirm.hidden=label.hidden=true;confirm.required=false;
 document.getElementById('accessCode').value='';confirm.value='';accessError('');m.hidden=false;document.body.classList.add('access-open');document.getElementById('accessCode').focus();
}
function closeAccess(){document.getElementById('scorekeeperAccess').hidden=true;document.body.classList.remove('access-open');document.getElementById('accessCode').value='';document.getElementById('accessConfirm').value=''}
function secureStorage(){try{const k='rah-storage-test';localStorage.setItem(k,'1');localStorage.removeItem(k);return true}catch(_){return false}}
async function submitAccess(event){
 event.preventDefault();const input=document.getElementById('accessCode');
 if(Date.now()<accessLockedUntil){accessError('Too many attempts. Try again shortly.');return}
 if(RAH_HOSTED){
  try{const r=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code:input.value})});
   if(!r.ok){input.value='';accessError(r.status===429?'Too many attempts — try again later.':'Incorrect scorekeeper code.');return}
  }catch(_){accessError('Cannot connect to scorekeeper server.');return}
 }else if(input.value!=='6387') {accessError('Incorrect scorekeeper code.');input.value='';return}
 edit=true;closeAccess();closeProfile();render();notify('Scorekeeper unlocked');
}

