state={...blank(),...previous,running:false};state.time=Math.max(0,Number(state.time)||0);state.eagles=Math.max(0,Number(state.eagles)||0);state.vipers=Math.max(0,Number(state.vipers)||0);
state.log=Array.isArray(state.log)?state.log.slice(0,120):[];state.plays=Array.isArray(state.plays)?state.plays.slice(0,300):[];state.players=Array.isArray(state.players)&&state.players.length?state.players:originalPlayers.map(p=>({...p}));
