function imageToDataUrl(file){return new Promise((resolve,reject)=>{
 if(!file.type.startsWith('image/')){reject(new Error('Choose an image file'));return}
 if(file.size>12*1024*1024){reject(new Error('Please choose an image under 12MB'));return}
 const obj=URL.createObjectURL(file),img=new Image();
 img.onload=()=>{try{const c=document.createElement('canvas'),side=520;c.width=side;c.height=side;const crop=Math.min(img.width,img.height),sx=(img.width-crop)/2,sy=(img.height-crop)/2;const ctx=c.getContext('2d');ctx.drawImage(img,sx,sy,crop,crop,0,0,side,side);resolve(c.toDataURL('image/jpeg',.74))}catch(e){reject(e)}finally{URL.revokeObjectURL(obj)}};
 img.onerror=()=>{URL.revokeObjectURL(obj);reject(new Error('Could not open image'))};img.src=obj;
})}


function rahQueueSave(){
 if(!RAH_HOSTED||rahLoading||!edit)return;
 const current={...state,running:!!state.running};
 rahSaveQueue=rahSaveQueue.then(async()=>{
  const r=await fetch('/api/game',{method:'PUT',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({game:current})});
  if(r.status===401||r.status===403){edit=false;render();notify('Scorekeeper session expired — please log in again');return}
  if(!r.ok){notify('Online sync failed — check connection');return}
  const response=await r.json();rahLastVersion=response.version;
 }).catch(()=>notify('Offline: game update could not reach server'));
}
async function rahLoadRemote(){
 if(!RAH_HOSTED){rahLoading=false;$('rahOnlineStatus').textContent='Offline file preview — open the hosted site for shared updates';return}
 try{
  const r=await fetch('/api/game',{cache:'no-store'});
  if(!r.ok)throw new Error('Unable to reach game server');
  const packet=await r.json();
  if(packet.version!==rahLastVersion){
    rahLastVersion=packet.version;
    if(!edit){
      state={...blank(),...packet.game};state.log=Array.isArray(state.log)?state.log:[];state.plays=Array.isArray(state.plays)?state.plays:[];
      if(state.running){anchorTime=Date.now();anchorSeconds=state.time;lastTickValue=state.time}
      render();fillPlayers();
    }
  }
  $('rahOnlineStatus').textContent='Connected · Changes appear for everyone automatically';
 }catch(err){$('rahOnlineStatus').textContent='Waiting for connection · '+err.message}
 finally{rahLoading=false}
}
function rahConnect(){
 if(!RAH_HOSTED)return;
 rahSSE=new EventSource('/api/events');
 rahSSE.addEventListener('game',()=>{if(!edit)rahLoadRemote()});
 rahSSE.onopen=()=>{$('rahOnlineStatus').textContent='LIVE CONNECTED · Shared scoreboard and play updates'};
 rahSSE.onerror=()=>{$('rahOnlineStatus').textContent='Reconnecting to live updates…'};
}
function rahBase64UrlToBytes(data){const base64=data.replace(/-/g,'+').replace(/_/g,'/');const binary=atob(base64);return Uint8Array.from(binary,c=>c.charCodeAt(0))}
function rahInitPush(){
 const button=$('rahPushButton');
 const supported=('serviceWorker'in navigator)&&('PushManager'in window)&&('Notification'in window);
 if(!supported){button.textContent='Notifications unavailable';button.disabled=true;return}
 if(!RAH_HOSTED){button.textContent='Host site to enable alerts';button.disabled=true;return}
 button.onclick=async()=>{
  try{
   if(Notification.permission==='denied')throw new Error('Notifications blocked in iPhone Settings');
   const permission=await Notification.requestPermission();
   if(permission!=='granted')throw new Error('Notification permission not granted');
   const register=await navigator.serviceWorker.ready;
   const info=await fetch('/api/push-config');const data=await info.json();
   if(!data.publicKey)throw new Error('Web push VAPID keys are not configured on the server');
   const sub=await register.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:rahBase64UrlToBytes(data.publicKey)});
   const result=await fetch('/api/web-subscriptions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({subscription:sub.toJSON(),preference:$('rahPushPreference').value})});
   if(!result.ok)throw new Error('Subscription not saved on server');
   button.textContent='✓ ALERTS ON';notify('iPhone alerts enabled for '+$('rahPushPreference').selectedOptions[0].text);
  }catch(err){notify(err.message);$('rahOnlineStatus').textContent=err.message+' · On iPhone, first use Safari > Share > Add to Home Screen'}
 };
}

function save(){try{localStorage.setItem(KEY,JSON.stringify({...state,running:false}))}catch(_){} rahQueueSave();}
function notify(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(notify.t);notify.t=setTimeout(()=>$('toast').classList.remove('show'),2500)}
function logEvent(msg){state.log.unshift({text:msg,period:period(state.quarter),time:formatTime(state.time)});state.log=state.log.slice(0,120)}
function pushUndo(){undoStack.push(JSON.parse(JSON.stringify({...state,running:false})));if(undoStack.length>50)undoStack.shift()}
function mutate(fn,event){if(!edit)return;pushUndo();fn();if(event)logEvent(event);save();render()}
function stopTimer(){if(state.running){state.time=Math.max(0,Math.ceil(anchorSeconds-(Date.now()-anchorTime)/1000));state.running=false;}}
function statsFor(id){
 const r={receptions:0,receiving:0,rushes:0,rushing:0,attempts:0,completions:0,passing:0,passingTds:0,td:0,interceptions:0,sacks:0,plays:0,fgMade:0,fgAtt:0,patMade:0,patAtt:0,twoMade:0,twoAtt:0,safeties:0,forcedFumbles:0,fumbleRecoveries:0,blockedKicks:0,kickoffs:0,punts:0,puntYards:0,kickoffReturns:0,puntReturns:0,returnYards:0,returnTds:0,defensiveConversions:0,penalties:0,penaltyYards:0};
 for(const p of state.plays){
  const type=p.type||'',n=Number(p.yards)||0,ret=Number(p.returnYards)||0,scored=!!(p.td||type.startsWith('td_'));
  if(p.player===id){
   r.plays++;
   if(type==='penalty'&&p.penaltyStatus==='accepted'){r.penalties++;r.penaltyYards+=Number(p.penaltyYards)||0}
   if(['pass','td_pass'].includes(type)){r.receptions++;r.receiving+=n}
   if(['rush','td_rush'].includes(type)){r.rushes++;r.rushing+=n}
   if(['interception','td_interception'].includes(type))r.interceptions++;
   if(type==='sack')r.sacks++;
   if(['forced_fumble'].includes(type))r.forcedFumbles++;
   if(['fumble_recovery','td_fumble'].includes(type))r.fumbleRecoveries++;
   if(['blocked_punt','blocked_field_goal','td_blocked_punt','td_blocked_fg'].includes(type))r.blockedKicks++;
   if(['kickoff_return','td_kickoff'].includes(type)){r.kickoffReturns++;r.returnYards+=n}
   if(['punt_return','td_punt'].includes(type)){r.puntReturns++;r.returnYards+=n}
   if(['td_interception','td_fumble','td_blocked_punt','td_blocked_fg'].includes(type))r.returnYards+=n;
   if(['td_interception','td_fumble','td_kickoff','td_punt','td_blocked_punt','td_blocked_fg'].includes(type)||(p.td&&['interception','fumble_recovery','kickoff_return','punt_return'].includes(type)))r.returnTds++;
   if(type==='kickoff'||type==='onside_kick')r.kickoffs++;
   if(type==='punt'){r.punts++;r.puntYards+=n}
   if(type==='safety')r.safeties++;
   if(type==='defensive_two_point')r.defensiveConversions++;
   if(scored)r.td++;
   if(type==='field_goal'){r.fgAtt++;if(p.result==='made')r.fgMade++}
   if(type==='pat'){r.patAtt++;if(p.result==='made')r.patMade++}
   if(type==='two_point'){r.twoAtt++;if(p.result==='made')r.twoMade++}
  }
  if(p.passer===id&&['pass','td_pass','incomplete','interception'].includes(type)){
   r.attempts++;if(['pass','td_pass'].includes(type)){r.completions++;r.passing+=n;if(scored)r.passingTds++}
  }
  if(p.otherPlayer===id && ['kickoff','punt'].includes(type) && p.result==='returned'){
   if(type==='kickoff')r.kickoffReturns++;else r.puntReturns++;
   r.returnYards+=ret;r.plays++;
  }
 }
 return r;
}

