 const res=$('playResult'),oldValue=res.value;
 $('passerField').hidden=!showPasser;$('otherPlayerField').hidden=!showOther;$('kickResultField').hidden=!(kicking||kickAction);$('kickTouchdownRow').hidden=!showTD;
 $('returnYardsField').hidden=!(showOther&&res.value==='returned');
 $('playPlayerLabel').textContent={pass:'RECEIVER',td_pass:'RECEIVER',rush:'BALL CARRIER',td_rush:'BALL CARRIER',incomplete:'INTENDED RECEIVER',interception:'DEFENDER',td_interception:'INTERCEPTING DEFENDER',fumble_recovery:'RECOVERING PLAYER',td_fumble:'RECOVERING PLAYER',sack:'DEFENDER',pat:'KICKER',two_point:'SCORING PLAYER',defensive_two_point:'DEFENSIVE SCORER',field_goal:'KICKER',kickoff:'KICKER',onside_kick:'KICKER',punt:'PUNTER',kickoff_return:'RETURNER',td_kickoff:'RETURNER',punt_return:'RETURNER',td_punt:'RETURNER',safety:'DEFENDER WHO MADE SAFETY',td_blocked_punt:'SCORING PLAYER',td_blocked_fg:'SCORING PLAYER',other:'PLAYER',penalty:'RESPONSIBLE PLAYER (OPTIONAL)'}[type]||'PLAYER INVOLVED';
 $('playYardsLabel').textContent=type==='field_goal'?'FIELD GOAL DISTANCE (YARDS)':type==='punt'?'PUNT DISTANCE (YARDS)':type==='kickoff'?'KICKOFF DISTANCE (YARDS)':kickAction?'KICK / PUNT DISTANCE (YDS)':type.includes('return')||['td_kickoff','td_punt','td_interception','td_fumble'].includes(type)?'RETURN YARDS':'PLAY YARDS';
 $('playYards').disabled=!showYards;$('playYards').required=showYards;
 $('playYards').min=(kicking||kickAction||type.startsWith('td_')||type==='kickoff_return'||type==='punt_return')?'0':'-99';
 if(!showYards)$('playYards').value='0';
 if(!showTD)$('playTouchdown').checked=false;
 const resultOptions=KICK_RESULTS[type]||[['made','GOOD / SUCCESSFUL'],['missed','MISSED / FAILED']];
 let current=[...res.options].map(o=>o.value);
 if(current.join('|')!==resultOptions.map(o=>o[0]).join('|')){res.replaceChildren();for(const [value,label] of resultOptions){let o=document.createElement('option');o.value=value;o.textContent=label;res.append(o)}if(resultOptions.some(o=>o[0]===oldValue))res.value=oldValue}
 $('returnYardsField').hidden=!(showOther&&res.value==='returned');
 $('otherPlayerField').hidden=!(showOther&&res.value==='returned');
 const points=selectedPlayPoints(type,$('playTouchdown').checked,res.value);
 $('playAutoScoreLabel').textContent=points?`Automatically add +${points} point${points===1?'':'s'} to the scoreboard` :type==='penalty'?'No points for penalties':'Automatically score if this play earns points (0 for this result)';
 const help=type==='kickoff'?'Kickoff (0 points): enter the kick distance. If returned, select the opponent who returned it and enter their return yardage. Use Kickoff Return TD only if they score.':type==='punt'?'Punt (0 points): enter punt distance, then choose the outcome. If returned, select the opposing returner and enter their return yards. Use Punt Return TD only if they score.':type==='kickoff_return'?'Regular kickoff return (0 points): select the RETURNING team, player and return yards. To score, choose Kickoff Return Touchdown instead.':type==='punt_return'?'Regular punt return (0 points): select the RETURNING team, player and return yards. To score, choose Punt Return Touchdown instead.':type==='onside_kick'?'Select the KICKING team; choose whether the kicking or receiving team recovered.':type==='safety'?'Select the DEFENDING team that earns 2 points.':type==='defensive_two_point'?'Select the defending team returning an opponent’s conversion attempt.':type.startsWith('td_')?'A touchdown automatically earns 6 points when auto-scoring is on.':kicking?'Choose Good / Missed. Only successful scoring attempts earn points.' :type==='penalty'?'Pick the called flag, penalized team, referee ruling, yardage and optional player. Penalties are logged at 0 points.':'Choose the player involved and add the play details.';
 $('playHelp').textContent=help;
 const teamLabel=document.querySelector('label[for="playTeam"]');if(teamLabel)teamLabel.textContent=type==='penalty'?'TEAM BEING PENALIZED':type==='safety'||type==='defensive_two_point'?'TEAM SCORING ON DEFENSE':kickAction?'KICKING / PUNTING TEAM':'TEAM';
